/**
 * Lightweight in-process pub/sub for raw source-file changes.
 *
 * The change detector already observes builder file-system events (see
 * `StoryDependencyGraphService`); this channel re-broadcasts them to any
 * dev-server consumer that only cares that *something* changed — most notably
 * the review addon, which uses it to mark a cached review as stale.
 *
 * State is module-level: the dev server is long-lived and there is a single
 * detector per process, so a single listener set is the right scope.
 */

export type SourceFileChangeListener = (event: FileChangeEvent) => void;

const listeners = new Set<SourceFileChangeListener>();

/**
 * Register a listener for source-file changes.
 *
 * @returns an unsubscribe function that stops the listener from receiving
 * further events. Calling it more than once is safe.
 */
export function subscribeToSourceFileChanges(listener: SourceFileChangeListener): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

/**
 * Deliver a {@link FileChangeEvent} to every registered listener.
 *
 * A throwing listener must not prevent the others from running, so each call is
 * isolated: errors are swallowed rather than propagated to the caller.
 */
export function notifySourceFileChange(event: FileChangeEvent): void {
  // Snapshot so a listener that (un)subscribes during delivery can't mutate the
  // set we're iterating.
  for (const listener of [...listeners]) {
    try {
      listener(event);
    } catch {
      // Isolate a faulty listener: the notifier can't reason about consumer
      // failures, and one bad listener must not starve the rest.
    }
  }
}

/**
 * Test-only: drop all registered listeners so no further events are delivered.
 */
export function internal_resetSourceFileChangeListeners(): void {
  listeners.clear();
}
